how_to_obtain.command:
python3 -c "
import yaml
cfg = yaml.safe_load(open('/etc/alertmanager/alertmanager.yml'))
receivers = {r['name']: r for r in cfg.get('receivers', [])}
print('Receivers:', list(receivers.keys()))
for r in cfg.get('route', {}).get('routes', []):
    if 'watchdog' in str(r.get('match', {})).lower() or 'watchdog' in str(r.get('matchers', [])).lower():
        print('Watchdog route found:', r)
" 2>/dev/null
